import { createRequire } from "node:module";
import assert from "node:assert/strict";
const { chromium } = createRequire(import.meta.url)("playwright");
const [base, executablePath, token] = process.argv.slice(2);
const browser = await chromium.launch({ executablePath, headless: true });
const context = await browser.newContext();
try {
  const login = await context.request.post(base + "/api/login", { data: { token } });
  assert.equal(login.status(), 200);
  const page = await context.newPage();
  const sent = [];
  page.on("request", (request) => { if (request.method() === "POST" && request.url().endsWith("/say")) sent.push(request.postDataJSON()); });
  const url = base + "/#demo/chat/aa144600-1111-4111-8111-111111111111";
  await page.goto(url);
  const boxes = page.locator(".caskpick");
  await boxes.first().waitFor();
  assert.equal(await boxes.count(), 3);
  for (let i=0; i<3; i++) assert.equal(await boxes.nth(i).getAttribute("aria-checked"), "true");
  const ta = page.locator("textarea.csay");
  const own = 'Дополню ещё один СЦ:\nЕсли задача была приписана к другой, то и у чата в заголовке задача меняется на актуальную.\n\n';
  await ta.fill(own);
  const comment = page.waitForResponse((r) => r.url().endsWith("/say") && r.request().method() === "POST");
  await page.getByRole("button", { name: "Отправить", exact: true }).click();
  assert.equal((await comment).status(), 200);
  assert.equal(sent.length, 1); assert.equal(sent[0].text, own); assert.equal(sent[0].selection, undefined);
  let state = await (await context.request.get(base + "/__scenario")).json();
  assert.doesNotMatch(state.doc, /решено человеком|пересмотр человеком/); assert.notEqual(state.waiting, "");
  await page.reload(); await boxes.first().waitFor();
  await page.locator('.msg.me').filter({hasText:'Дополню ещё один СЦ'}).first().waitFor();
  assert.equal(await page.locator('.askresume').count(), 0);
  assert.doesNotMatch(await page.locator('.chatfeed').innerText(), /Ответ с вложением панели|Ответ панели обработан|Продолжение XR-4/);
  const exact = '  ' + own + 'плюс, минус; "слова, как есть"  ';
  await ta.fill(exact); await boxes.nth(1).click();
  assert.equal(await ta.inputValue(), exact);
  await page.locator('.selection-preview .selection-attachment').waitFor();
  await page.reload(); await boxes.first().waitFor();
  assert.equal(await ta.inputValue(), exact);
  assert.equal(await boxes.nth(1).getAttribute('aria-checked'), 'false');
  await page.route('**/say', (route) => route.abort('failed'));
  const failed = page.waitForEvent('requestfailed', {predicate:(r)=>r.url().endsWith('/say')});
  await page.getByRole('button',{name:'Отправить',exact:true}).click(); await failed;
  await page.getByText('не ушло, дожимаю', {exact:true}).waitFor();
  const attempted = sent.at(-1); assert.equal(attempted.text,exact);
  assert.deepEqual(attempted.selection.questions[0].ids,['СЦ-1','СЦ-3']);
  await page.unroute('**/say');
  const retried = page.waitForResponse((r)=>r.url().endsWith('/say') && r.request().method()==='POST');
  await page.reload(); assert.equal((await retried).status(),200);
  assert.deepEqual(sent.at(-1),attempted);
  state = await (await context.request.get(base + '/__scenario')).json();
  assert.match(state.doc,/решено человеком [\d-]+: СЦ-1, СЦ-3/); assert.equal(state.waiting,'');
  await page.reload();
  await page.locator('.msg.me .selection-attachment').filter({hasText:'СЦ-1'}).first().waitFor();
  assert.equal(await page.locator('.askresume').count(),0);
  assert.doesNotMatch(await page.locator('.chatfeed').innerText(), /Ответ с вложением панели|Ответ панели обработан|Продолжение XR-4/);
  await context.request.get(base + '/__scenario?do=fresh');
  await page.reload(); await boxes.first().waitFor();
  assert.equal(await boxes.nth(0).getAttribute('aria-checked'),'true');
  assert.equal(await boxes.nth(1).getAttribute('aria-checked'),'false');
  assert.equal(await boxes.nth(2).getAttribute('aria-checked'),'true');
  await boxes.nth(0).click(); await boxes.nth(2).click();
  assert.equal(await ta.inputValue(),'');
  const decline = page.waitForResponse((r)=>r.url().endsWith('/say') && r.request().method()==='POST');
  await page.getByRole('button',{name:'Отправить',exact:true}).click(); assert.equal((await decline).status(),200);
  state = await (await context.request.get(base + '/__scenario')).json();
  assert.match(state.doc,/пересмотр человеком [\d-]+: отказ от всех/);
  await context.request.get(base + '/__scenario?do=fresh');
  await page.reload(); await boxes.first().waitFor();
  for (let i=0;i<3;i++) assert.equal(await boxes.nth(i).getAttribute('aria-checked'),'false');
  await page.locator('.msg.me .selection-attachment').filter({hasText:'отказ от всех'}).first().waitFor();
  await page.getByRole('button',{name:'Прикрепить выбор «сценарии»',exact:true}).click();
  await ta.fill('текст после отказа');
  await context.request.get(base + '/__scenario?do=reorder');
  state=await (await context.request.get(base+'/__scenario')).json(); const before=JSON.stringify(state);
  const stale=page.waitForResponse((r)=>r.url().endsWith('/say') && r.request().method()==='POST');
  await page.getByRole('button',{name:'Отправить',exact:true}).click(); assert.equal((await stale).status(),400);
  state=await (await context.request.get(base+'/__scenario')).json(); assert.equal(JSON.stringify(state),before);
  await context.request.get(base + '/__scenario?do=ordinary');
  await page.reload(); await boxes.first().waitFor();
  assert.equal(await boxes.count(),7);
  await ta.fill('  пояснение к сроку\nи выводу  ');
  await boxes.nth(4).click(); await boxes.nth(5).click();
  assert.equal(await ta.inputValue(),'  пояснение к сроку\nи выводу  ');
  const ordinary=page.waitForResponse((r)=>r.url().endsWith('/say') && r.request().method()==='POST');
  await page.getByRole('button',{name:'Отправить',exact:true}).click(); assert.equal((await ordinary).status(),200);
  assert.deepEqual(sent.at(-1).selection.questions.map((q)=>[q.fork,q.ids]),[['срок',['2']],['вывод',['1']]]);
  state=await (await context.request.get(base+'/__scenario')).json();
  assert.match(state.doc,/решено человеком [\d-]+: 7 дней/);
  assert.match(state.doc,/решено человеком [\d-]+: полный: нужен/);
  await page.reload();
  await page.locator('.msg.me .selection-attachment').filter({hasText:'«срок»: 7 дней'}).first().waitFor();
  assert.match(await page.locator('.msg.me').filter({hasText:'пояснение к сроку'}).first().locator('.mm').innerText(),/\d{2}:\d{2}/);
  console.log(JSON.stringify({sent:sent.length,defaultAll:true,freeText:true,exactText:true,reloadRetry:true,selectionOnly:true,explicitRefusal:true,stale:400,datedHistory:true,noContinuation:true}));
} finally { await context.close(); await browser.close(); }
